package keyescrow

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"testing"
	"time"
)

// Failure modes E1-E10 of docs/archive/definitions/choir-launch-fp9-keys-recovery-2026-10-21.md
// ("Sealed escrow key"), written before the code. Every key here is
// generated by the test; nothing is read from the host.

func testKEK(t *testing.T, fill byte) []byte {
	t.Helper()
	return bytes.Repeat([]byte{fill}, 32)
}

func writeKEKFile(t *testing.T, dir string, kek []byte, mode os.FileMode, asBase64 bool) string {
	t.Helper()
	path := filepath.Join(dir, "key-escrow-kek")
	content := kek
	if asBase64 {
		content = []byte(base64.StdEncoding.EncodeToString(kek) + "\n")
	}
	if err := os.WriteFile(path, content, mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
	return path
}

func writePlainKey(t *testing.T, path string) PrivateKey {
	t.Helper()
	priv, _, err := GenerateKeyPair()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(base64.RawStdEncoding.EncodeToString(priv[:])+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	return priv
}

func mustFingerprint(t *testing.T, priv PrivateKey) string {
	t.Helper()
	pub, err := priv.Public()
	if err != nil {
		t.Fatal(err)
	}
	return Fingerprint(pub)
}

func TestSealedPrivateKeyRoundTrip(t *testing.T) {
	priv, _, err := GenerateKeyPair()
	if err != nil {
		t.Fatal(err)
	}
	kek := testKEK(t, 0x41)
	sealed, err := SealPrivateKey(priv, kek)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Contains(sealed, []byte(base64.RawStdEncoding.EncodeToString(priv[:]))) {
		t.Fatal("sealed file carries the private key in the clear")
	}
	var header struct {
		Version         int    `json:"version"`
		Purpose         string `json:"purpose"`
		PublicKeySHA256 string `json:"public_key_sha256"`
	}
	if err := json.Unmarshal(sealed, &header); err != nil {
		t.Fatal(err)
	}
	if header.Version != SealedKeyVersion || header.Purpose != SealPurposeEscrowPrivateKey || header.PublicKeySHA256 != mustFingerprint(t, priv) {
		t.Fatalf("unexpected sealed header: %+v", header)
	}
	got, err := OpenSealedPrivateKey(sealed, kek)
	if err != nil {
		t.Fatal(err)
	}
	if got != priv {
		t.Fatal("opened key differs")
	}
}

// E1: a wrong KEK does not open, and the error carries no key bytes.
func TestSealedPrivateKeyWrongKEK(t *testing.T) {
	priv, _, _ := GenerateKeyPair()
	kek := testKEK(t, 0x41)
	sealed, err := SealPrivateKey(priv, kek)
	if err != nil {
		t.Fatal(err)
	}
	_, err = OpenSealedPrivateKey(sealed, testKEK(t, 0x42))
	if !errors.Is(err, ErrSealedKey) {
		t.Fatalf("wrong KEK: err = %v, want ErrSealedKey", err)
	}
	assertNoSecretInError(t, err, priv[:], kek)
}

// E5: a truncated or edited sealed file is refused.
func TestSealedPrivateKeyTamper(t *testing.T) {
	priv, _, _ := GenerateKeyPair()
	kek := testKEK(t, 0x41)
	sealed, err := SealPrivateKey(priv, kek)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := OpenSealedPrivateKey(sealed[:len(sealed)/2], kek); !errors.Is(err, ErrSealedKey) {
		t.Fatalf("truncated: err = %v", err)
	}
	var record map[string]any
	if err := json.Unmarshal(sealed, &record); err != nil {
		t.Fatal(err)
	}
	ct := record["ciphertext"].(string)
	flipped := []byte(ct)
	if flipped[3] == 'A' {
		flipped[3] = 'B'
	} else {
		flipped[3] = 'A'
	}
	record["ciphertext"] = string(flipped)
	edited, _ := json.Marshal(record)
	if _, err := OpenSealedPrivateKey(edited, kek); !errors.Is(err, ErrSealedKey) {
		t.Fatalf("edited ciphertext: err = %v", err)
	}
	// A swapped fingerprint is caught by the associated data.
	_ = json.Unmarshal(sealed, &record)
	record["public_key_sha256"] = strings.Repeat("0", 64)
	edited, _ = json.Marshal(record)
	if _, err := OpenSealedPrivateKey(edited, kek); !errors.Is(err, ErrSealedKey) {
		t.Fatalf("edited fingerprint: err = %v", err)
	}
	// An unknown field is refused rather than ignored.
	_ = json.Unmarshal(sealed, &record)
	record["extra"] = "x"
	edited, _ = json.Marshal(record)
	if _, err := OpenSealedPrivateKey(edited, kek); !errors.Is(err, ErrSealedKey) {
		t.Fatalf("unknown field: err = %v", err)
	}
}

// E6: a sealed file for another purpose is not loaded as the escrow key,
// even with the purpose field rewritten (the purpose is associated data).
func TestSealedPrivateKeyOtherPurpose(t *testing.T) {
	priv, _, _ := GenerateKeyPair()
	kek := testKEK(t, 0x41)
	sealed, err := sealPrivateKeyForPurpose(priv, kek, "choir/other/v1")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := OpenSealedPrivateKey(sealed, kek); !errors.Is(err, ErrSealedKey) {
		t.Fatalf("other purpose: err = %v", err)
	}
	var record map[string]any
	_ = json.Unmarshal(sealed, &record)
	record["purpose"] = SealPurposeEscrowPrivateKey
	edited, _ := json.Marshal(record)
	if _, err := OpenSealedPrivateKey(edited, kek); !errors.Is(err, ErrSealedKey) {
		t.Fatalf("relabelled purpose: err = %v", err)
	}
}

func TestParseSealMode(t *testing.T) {
	for in, want := range map[string]SealMode{"": SealOff, "off": SealOff, "permit": SealPermit, "require": SealRequire, " require ": SealRequire} {
		got, err := ParseSealMode(in)
		if err != nil || got != want {
			t.Fatalf("ParseSealMode(%q) = %q, %v; want %q", in, got, err, want)
		}
	}
	for _, in := range []string{"on", "true", "REQUIRE", "yes"} {
		if _, err := ParseSealMode(in); err == nil {
			t.Fatalf("ParseSealMode(%q) accepted an unknown mode", in)
		}
	}
}

func TestSealConfigFromEnv(t *testing.T) {
	env := func(m map[string]string) func(string) string { return func(k string) string { return m[k] } }
	cfg, err := SealConfigFromEnv(env(nil))
	if err != nil || cfg.Mode != SealOff {
		t.Fatalf("unset: %+v %v", cfg, err)
	}
	// Permit or require without a KEK path is a configuration error, not off.
	if _, err := SealConfigFromEnv(env(map[string]string{EnvSealMode: "permit"})); err == nil {
		t.Fatal("permit without a KEK path accepted")
	}
	if _, err := SealConfigFromEnv(env(map[string]string{EnvSealMode: "require", EnvKEKPath: "relative/kek"})); err == nil {
		t.Fatal("relative KEK path accepted")
	}
	if _, err := SealConfigFromEnv(env(map[string]string{EnvSealMode: "bogus", EnvKEKPath: "/x"})); err == nil {
		t.Fatal("unknown mode accepted")
	}
	cfg, err = SealConfigFromEnv(env(map[string]string{EnvSealMode: "require", EnvKEKPath: "/run/credentials/x/kek"}))
	if err != nil || cfg.Mode != SealRequire || cfg.KEKPath != "/run/credentials/x/kek" {
		t.Fatalf("require: %+v %v", cfg, err)
	}
}

// E7: the KEK file must be owner-only, a regular file, never a link, and
// exactly 32 bytes raw or as base64 text.
func TestLoadKEK(t *testing.T) {
	kek := testKEK(t, 0x41)
	for _, tc := range []struct {
		name   string
		mode   os.FileMode
		base64 bool
	}{{"raw 0400", 0o400, false}, {"raw 0600", 0o600, false}, {"base64 0400", 0o400, true}} {
		dir := t.TempDir()
		path := writeKEKFile(t, dir, kek, tc.mode, tc.base64)
		got, err := LoadKEK(path)
		if err != nil || !bytes.Equal(got, kek) {
			t.Fatalf("%s: %v", tc.name, err)
		}
	}
	for _, mode := range []os.FileMode{0o440, 0o604, 0o644, 0o640} {
		dir := t.TempDir()
		path := writeKEKFile(t, dir, kek, mode, false)
		if _, err := LoadKEK(path); err == nil {
			t.Fatalf("mode %o accepted", mode)
		}
	}
	dir := t.TempDir()
	short := filepath.Join(dir, "key-escrow-kek-short")
	if err := os.WriteFile(short, kek[:16], 0o400); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadKEK(short); err == nil {
		t.Fatal("16-byte KEK accepted")
	}
	real := writeKEKFile(t, dir, kek, 0o400, false)
	link := filepath.Join(dir, "key-escrow-kek-link")
	if err := os.Symlink(real, link); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadKEK(link); err == nil {
		t.Fatal("KEK through a symlink accepted")
	}
	if _, err := LoadKEK(dir); err == nil {
		t.Fatal("a directory accepted as KEK")
	}
	if _, err := LoadKEK("relative"); err == nil {
		t.Fatal("relative KEK path accepted")
	}
	if _, err := LoadKEK(filepath.Join(dir, "absent")); err == nil {
		t.Fatal("absent KEK accepted")
	}
}

// E9: off is exactly today: a plaintext file loads, an absent file is
// generated (0600). A sealed file in off is refused with a reason, never
// regenerated over.
func TestLoadPrivateKeyOffIsToday(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "key-escrow-key")
	priv := writePlainKey(t, path)
	got, state, err := LoadPrivateKey(path, SealConfig{Mode: SealOff})
	if err != nil || got != priv || state != KeyFilePlaintext {
		t.Fatalf("off plaintext: state=%s err=%v", state, err)
	}
	absent := filepath.Join(dir, "gen", "key")
	gen, state, err := LoadPrivateKey(absent, SealConfig{Mode: SealOff})
	if err != nil || state != KeyFileGenerated {
		t.Fatalf("off absent: state=%s err=%v", state, err)
	}
	again, _, err := LoadPrivateKey(absent, SealConfig{Mode: SealOff})
	if err != nil || again != gen {
		t.Fatal("off reload differs from the generated key")
	}

	kek := testKEK(t, 0x41)
	sealedPath := filepath.Join(dir, "sealed")
	sealed, _ := SealPrivateKey(priv, kek)
	if err := os.WriteFile(sealedPath, sealed, 0o600); err != nil {
		t.Fatal(err)
	}
	if _, _, err := LoadPrivateKey(sealedPath, SealConfig{Mode: SealOff}); err == nil || !strings.Contains(err.Error(), EnvSealMode) {
		t.Fatalf("E2: sealed file in off: err = %v, want a refusal naming %s", err, EnvSealMode)
	}
	after, _ := os.ReadFile(sealedPath)
	if !bytes.Equal(after, sealed) {
		t.Fatal("E2: the sealed file was rewritten")
	}
}

// E4: a missing file in permit or require is an error, never a new key.
func TestLoadPrivateKeyNeverGeneratesWhenSealed(t *testing.T) {
	kek := testKEK(t, 0x41)
	for _, mode := range []SealMode{SealPermit, SealRequire} {
		dir := t.TempDir()
		kekPath := writeKEKFile(t, dir, kek, 0o400, false)
		path := filepath.Join(dir, "key-escrow-key")
		if _, _, err := LoadPrivateKey(path, SealConfig{Mode: mode, KEKPath: kekPath}); err == nil {
			t.Fatalf("%s: missing key file accepted", mode)
		}
		if _, err := os.Stat(path); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("%s: a key file was created", mode)
		}
	}
}

// E3 and permit: require refuses plaintext; permit accepts both and says
// which one it read.
func TestLoadPrivateKeyPermitAndRequire(t *testing.T) {
	kek := testKEK(t, 0x41)
	dir := t.TempDir()
	kekPath := writeKEKFile(t, dir, kek, 0o400, false)
	plainPath := filepath.Join(dir, "plain")
	priv := writePlainKey(t, plainPath)
	sealedPath := filepath.Join(dir, "sealed")
	sealed, _ := SealPrivateKey(priv, kek)
	if err := os.WriteFile(sealedPath, sealed, 0o600); err != nil {
		t.Fatal(err)
	}

	got, state, err := LoadPrivateKey(plainPath, SealConfig{Mode: SealPermit, KEKPath: kekPath})
	if err != nil || got != priv || state != KeyFilePlaintext {
		t.Fatalf("permit plaintext: state=%s err=%v", state, err)
	}
	got, state, err = LoadPrivateKey(sealedPath, SealConfig{Mode: SealPermit, KEKPath: kekPath})
	if err != nil || got != priv || state != KeyFileSealed {
		t.Fatalf("permit sealed: state=%s err=%v", state, err)
	}
	if _, _, err := LoadPrivateKey(plainPath, SealConfig{Mode: SealRequire, KEKPath: kekPath}); err == nil {
		t.Fatal("E3: require accepted a plaintext key file")
	}
	got, state, err = LoadPrivateKey(sealedPath, SealConfig{Mode: SealRequire, KEKPath: kekPath})
	if err != nil || got != priv || state != KeyFileSealed {
		t.Fatalf("require sealed: state=%s err=%v", state, err)
	}
	// E1 through the loader: a different KEK refuses, and leaves the file.
	otherDir := t.TempDir()
	otherKEK := writeKEKFile(t, otherDir, testKEK(t, 0x42), 0o400, false)
	if _, _, err := LoadPrivateKey(sealedPath, SealConfig{Mode: SealRequire, KEKPath: otherKEK}); err == nil {
		t.Fatal("E1: wrong KEK opened the sealed key")
	}
	// E7 through the loader: a loose KEK refuses even for a plaintext file.
	loose := writeKEKFile(t, t.TempDir(), kek, 0o644, false)
	if _, _, err := LoadPrivateKey(plainPath, SealConfig{Mode: SealPermit, KEKPath: loose}); err == nil {
		t.Fatal("E7: a world-readable KEK accepted")
	}
}

// E8: seal replaces the file only after proving the same public key, and
// unseal is the way back to the same key.
func TestSealAndUnsealKeyFile(t *testing.T) {
	kek := testKEK(t, 0x41)
	dir := t.TempDir()
	path := filepath.Join(dir, "key-escrow-key")
	priv := writePlainKey(t, path)
	want := mustFingerprint(t, priv)

	fp, err := SealKeyFile(path, kek)
	if err != nil || fp != want {
		t.Fatalf("seal: fp=%s err=%v", fp, err)
	}
	info, err := os.Stat(path)
	if err != nil || info.Mode().Perm() != 0o600 {
		t.Fatalf("sealed file mode: %v %v", info, err)
	}
	insp, err := InspectKeyFile(path, kek)
	if err != nil || insp.State != KeyFileSealed || !insp.Opens || insp.PublicKeySHA256 != want {
		t.Fatalf("inspect sealed: %+v %v", insp, err)
	}
	// Sealing a sealed file is refused, not double-wrapped.
	if _, err := SealKeyFile(path, kek); err == nil {
		t.Fatal("sealed twice")
	}
	// Unsealing with the wrong KEK leaves the sealed file untouched.
	before, _ := os.ReadFile(path)
	if _, err := UnsealKeyFile(path, testKEK(t, 0x42)); err == nil {
		t.Fatal("unseal with the wrong KEK succeeded")
	}
	after, _ := os.ReadFile(path)
	if !bytes.Equal(before, after) {
		t.Fatal("a failed unseal changed the file")
	}
	fp, err = UnsealKeyFile(path, kek)
	if err != nil || fp != want {
		t.Fatalf("unseal: fp=%s err=%v", fp, err)
	}
	got, state, err := LoadPrivateKey(path, SealConfig{Mode: SealOff})
	if err != nil || got != priv || state != KeyFilePlaintext {
		t.Fatalf("after unseal: state=%s err=%v", state, err)
	}
	// No temporary file is left beside the key.
	entries, _ := os.ReadDir(dir)
	if len(entries) != 1 {
		names := []string{}
		for _, e := range entries {
			names = append(names, e.Name())
		}
		t.Fatalf("left files: %v", names)
	}
	// Sealing a missing file is an error and creates nothing.
	if _, err := SealKeyFile(filepath.Join(dir, "absent"), kek); err == nil {
		t.Fatal("sealed a missing file")
	}
	if _, err := os.Stat(filepath.Join(dir, "absent")); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("seal of a missing file created one")
	}
}

func TestInspectKeyFileStates(t *testing.T) {
	kek := testKEK(t, 0x41)
	dir := t.TempDir()
	insp, err := InspectKeyFile(filepath.Join(dir, "absent"), nil)
	if err != nil || insp.State != KeyFileMissing || insp.Opens {
		t.Fatalf("missing: %+v %v", insp, err)
	}
	path := filepath.Join(dir, "plain")
	priv := writePlainKey(t, path)
	insp, err = InspectKeyFile(path, nil)
	if err != nil || insp.State != KeyFilePlaintext || !insp.Opens || insp.PublicKeySHA256 != mustFingerprint(t, priv) {
		t.Fatalf("plaintext: %+v %v", insp, err)
	}
	if _, err := SealKeyFile(path, kek); err != nil {
		t.Fatal(err)
	}
	// Without the KEK, a sealed file reports its recorded fingerprint and
	// that it was not opened.
	insp, err = InspectKeyFile(path, nil)
	if err != nil || insp.State != KeyFileSealed || insp.Opens || insp.PublicKeySHA256 != mustFingerprint(t, priv) {
		t.Fatalf("sealed without KEK: %+v %v", insp, err)
	}
	insp, err = InspectKeyFile(path, testKEK(t, 0x42))
	if err != nil || insp.State != KeyFileSealed || insp.Opens {
		t.Fatalf("sealed with wrong KEK: %+v %v", insp, err)
	}
}

func TestGenerateKEKFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "key-escrow-kek")
	if err := GenerateKEKFile(path); err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(path)
	if err != nil || info.Mode().Perm() != 0o400 {
		t.Fatalf("kek mode: %v %v", info, err)
	}
	kek, err := LoadKEK(path)
	if err != nil || len(kek) != 32 {
		t.Fatalf("generated KEK does not load: %v", err)
	}
	if err := GenerateKEKFile(path); err == nil {
		t.Fatal("GenerateKEKFile overwrote an existing KEK")
	}
}

// E10: errors never carry key material.
func assertNoSecretInError(t *testing.T, err error, secrets ...[]byte) {
	t.Helper()
	if err == nil {
		return
	}
	msg := err.Error()
	for _, s := range secrets {
		for _, enc := range []string{base64.RawStdEncoding.EncodeToString(s), base64.StdEncoding.EncodeToString(s), string(s)} {
			if enc != "" && strings.Contains(msg, enc) {
				t.Fatalf("error text carries key material: %q", msg)
			}
		}
	}
}

func TestLoaderErrorsCarryNoKeyMaterial(t *testing.T) {
	kek := testKEK(t, 0x41)
	dir := t.TempDir()
	kekPath := writeKEKFile(t, dir, kek, 0o400, false)
	path := filepath.Join(dir, "plain")
	priv := writePlainKey(t, path)
	_, _, err := LoadPrivateKey(path, SealConfig{Mode: SealRequire, KEKPath: kekPath})
	assertNoSecretInError(t, err, priv[:], kek)
	// A corrupt plaintext file reports no content.
	if err := os.WriteFile(path, []byte("not-a-key-but-secret-looking\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	_, _, err = LoadPrivateKey(path, SealConfig{Mode: SealPermit, KEKPath: kekPath})
	if err == nil || strings.Contains(err.Error(), "secret-looking") {
		t.Fatalf("corrupt plaintext: err = %v", err)
	}
}

// B3 (bunch 4b review): the backup excludes KEK files by name, so a KEK is
// accepted, and generated, only under that name. A KEK at
// /var/lib/go-choir/secrets/custom-kek would ride in the backup beside the
// sealed key.
func TestKEKNameIsEnforced(t *testing.T) {
	kek := testKEK(t, 0x41)
	dir := t.TempDir()
	for _, name := range []string{"custom-kek", "kek", "escrow-kek", "key-escrow-ke"} {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, kek, 0o400); err != nil {
			t.Fatal(err)
		}
		if _, err := LoadKEK(path); err == nil {
			t.Fatalf("a KEK named %q was accepted", name)
		}
		if err := GenerateKEKFile(filepath.Join(dir, "new-"+name)); err == nil {
			t.Fatalf("a KEK named new-%q was generated", name)
		}
	}
	for _, name := range []string{"key-escrow-kek", "key-escrow-kek.2026"} {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, kek, 0o400); err != nil {
			t.Fatal(err)
		}
		if _, err := LoadKEK(path); err != nil {
			t.Fatalf("a KEK named %q was refused: %v", name, err)
		}
	}
	// Under permit a misnamed KEK is a configuration error at start.
	plain := filepath.Join(dir, "key-escrow-key")
	writePlainKey(t, plain)
	if _, _, err := LoadPrivateKey(plain, SealConfig{Mode: SealPermit, KEKPath: filepath.Join(dir, "custom-kek")}); err == nil {
		t.Fatal("permit started with a misnamed KEK")
	}
}

// B3: the name the loader requires and the pattern the daily backup
// excludes are one rule; this keeps them from drifting apart.
func TestKEKNameMatchesTheBackupExclusion(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "scripts", "off-host-backup.sh"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), `"`+KEKNamePrefix+`*"`) {
		t.Fatalf("scripts/off-host-backup.sh does not exclude %q", KEKNamePrefix+"*")
	}
}

// Repair round 2 (bunch 31 review, low): a FIFO or device at the KEK or key
// path must be refused at once, not hang the service at start: the file is
// opened non-blocking and without following a link, then checked to be a
// regular file before any read.
func TestKeyFilesThatAreNotRegularAreRefusedWithoutBlocking(t *testing.T) {
	dir := t.TempDir()
	kekFifo := filepath.Join(dir, "key-escrow-kek")
	keyFifo := filepath.Join(dir, "key-escrow-key")
	for _, p := range []string{kekFifo, keyFifo} {
		if err := syscall.Mkfifo(p, 0o600); err != nil {
			t.Skipf("mkfifo: %v", err)
		}
	}
	type result struct{ err error }
	run := func(name string, fn func() error) {
		t.Helper()
		done := make(chan result, 1)
		go func() { done <- result{fn()} }()
		select {
		case r := <-done:
			if r.err == nil {
				t.Fatalf("%s: a FIFO was accepted", name)
			}
		case <-time.After(3 * time.Second):
			t.Fatalf("%s: blocked opening a FIFO", name)
		}
	}
	run("LoadKEK", func() error { _, err := LoadKEK(kekFifo); return err })
	run("InspectKeyFile", func() error { _, err := InspectKeyFile(keyFifo, nil); return err })
	kek := writeKEKFile(t, t.TempDir(), testKEK(t, 0x41), 0o400, false)
	run("LoadPrivateKey require", func() error {
		_, _, err := LoadPrivateKey(keyFifo, SealConfig{Mode: SealRequire, KEKPath: kek})
		return err
	})
}
